static double fast_pow(double x, int32_t n) {
  if (n == 0) { return 1.0; }
  if (n == 1) { return x; }
  double t = fast_pow(x, n / 2);
  return n & 1 ? t * t * x : t * t;
}

static double myPow(double x, int n) {
  return n < 0 ? 1 / fast_pow(x, -(int32_t)(n)) : fast_pow(x, (int32_t)n);
}

class Solution {
public:
  static double fast_pow(double x, int32_t n) {
    if (n == 0) { return 1.0; }
    if (n == 1) { return x; }
    double t = fast_pow(x, n / 2);
    return n & 1 ? t * t * x : t * t;
  }
  double myPow(double x, int n) {
    return n < 0 ? 1 / fast_pow(x, -(int32_t)(n)) : fast_pow(x, (int32_t)n);
  }
};

func myPow(x float64, n int) float64 {
	e := int64(n)
	if e < 0 {
		x = 1 / x
		e = -e
	}
	res := 1.0
	for e > 0 {
		if e&1 == 1 {
			res *= x
		}
		x *= x
		e >>= 1
	}
	return res
}

class Solution {
  private double fastPow(double x, long n) {
    if (n == 0) {
      return 1.0;
    }
    double half = fastPow(x, n / 2);
    if (n % 2 == 0) {
      return half * half;
    } else {
      return half * half * x;
    }
  }

  public double myPow(double x, int n) {
    long N = n;
    if (N < 0) {
      x = 1 / x;
      N = -N;
    }

    return fastPow(x, N);
  }
}

class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n < 0:
            x = 1 / x
            n = -n
        res = 1.0
        while n > 0:
            if n & 1:
                res *= x
            x *= x
            n >>= 1
        return res

impl Solution {
  pub fn my_pow(x: f64, n: i32) -> f64 {
    let mut x = x;
    let mut e = n as i64;
    if e < 0 {
      x = 1.0 / x;
      e = -e;
    }
    let mut res = 1.0;
    while e > 0 {
      if e & 1 == 1 {
        res *= x;
      }
      x *= x;
      e >>= 1;
    }
    res
  }
}

const myPow = (x: number, n: number): number => {
  let base = x;
  let e = n;
  if (e < 0) {
    base = 1 / base;
    e = -e;
  }
  let res = 1;
  while (e > 0) {
    if (e & 1) res *= base;
    base *= base;
    e = Math.floor(e / 2);
  }
  return res;
};
